Object.assign(SNIP,{"l22func": "const int MAX = 100;\n// chiều thứ hai PHẢI ghi kích thước (là hằng), chiều thứ nhất có thể để trống\nint tongMaTran(int a[][MAX], int n, int m) {\n    int s = 0;\n    for (int i = 0; i < n; i++)\n        for (int j = 0; j < m; j++) s += a[i][j];\n    return s;\n}", "l22decl": "int a[3][4];                    // 3 hàng, mỗi hàng 4 cột: 12 ô\nint b[2][3] = {{1, 2, 3},       // hàng 0\n               {4, 5, 6}};      // hàng 1\nint c[3][3] = {};               // toàn số 0\n// b[1][2] là hàng 1, cột 2 → giá trị 6", "l22loop": "#include <iostream>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;                       // n hàng, m cột\n    int a[100][100];\n    for (int i = 0; i < n; i++)          // vòng ngoài: từng hàng\n        for (int j = 0; j < m; j++)      // vòng trong: từng cột của hàng i\n            cin >> a[i][j];\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < m; j++) cout << a[i][j] << \" \";\n        cout << \"\\n\";                    // hết một hàng thì xuống dòng\n    }\n    return 0;\n}"});PRESET_NOTES["l22"]={"Ví dụ: Khai báo và in bảng": "Vòng ngoài i chạy theo hàng, vòng trong j chạy theo cột. Ô đang in (a[i][j]) được tô đậm: đi hết hàng 0 rồi mới xuống hàng 1.", "Ví dụ: Nhập bảng và tổng từng hàng": "Khai báo bảng 10 × 10 nhưng chỉ dùng n hàng, m cột. Tổng hàng i: giữ nguyên i, cho j chạy hết một hàng. Biến s khai báo trong vòng ngoài nên mỗi hàng bắt đầu lại từ 0.", "Ví dụ: Tổng từng cột": "Đổi vai hai vòng lặp: vòng ngoài là cột j, vòng trong là hàng i. Ô tô đậm đi từ trên xuống dưới trong một cột.", "Ví dụ: Hai đường chéo": "Chỉ cần một vòng lặp: đường chéo chính là a[i][i], đường chéo phụ là a[i][n - 1 - i]. Các ô được đọc trong mỗi bước có viền xanh.", "Ví dụ: Ma trận chuyển vị": "Ma trận 2 × 3 thành 3 × 2: ô a[i][j] được chép sang b[j][i]. Hàng của a trở thành cột của b.", "Ví dụ: Đếm ô kề bằng dx, dy": "Bốn ô kề của (i, j) là (i + dx[k], j + dy[k]) với k = 0..3: trên, dưới, trái, phải. Phải kiểm tra x, y còn trong lưới TRƯỚC khi đọc g[x][y] (nhờ && dừng sớm).", "Ví dụ: Truyền bảng vào hàm": "Tham số int a[][MAX]: chiều thứ hai ghi rõ kích thước (hằng MAX). Hàm nhận chính bảng của main, không chép.", "Lỗi: nhầm hàng và cột": "Viết a[j][i] thay vì a[i][j]: khi j = 2, a[2] là hàng thứ ba, không tồn tại (bảng chỉ có 2 hàng). Trình mô phỏng dừng; máy thật thì đọc nhầm vùng nhớ."};EX_HINTS["l22"]=[["Vòng ngoài theo hàng i; khai báo s = 0 bên trong vòng ngoài để mỗi hàng bắt đầu lại từ 0.", "Vòng trong cộng a[i][j] với j = 0..m-1, xong vòng trong thì in s."], ["Ô đầu tiên luôn là ứng viên ban đầu (kể cả khi mọi số đều âm).", "Chỉ cập nhật khi x > lon (lớn hơn hẳn) để giữ lần xuất hiện ĐẦU TIÊN.", "Không bắt buộc lưu cả bảng: có thể xét từng số ngay khi đọc."], ["Không cần tạo mảng mới: in hàng j của ma trận chuyển vị chính là in cột j của ma trận gốc.", "Vòng ngoài chạy theo cột j (0..m-1), vòng trong theo hàng i (0..n-1), in a[i][j]."]];
